export const CONVERSATION_PROTOCOL_VERSION = 1 as const;

export type JsonPrimitive = string | number | boolean | null;
export type JsonValue = JsonPrimitive | JsonValue[] | { [key: string]: JsonValue };

export type ConversationRole = "user" | "assistant" | "system" | "tool";
export type AudioEncoding = "pcm16" | "g711_ulaw" | "g711_alaw" | "opus" | "mp3" | "wav" | "webm";

interface EventEnvelope<TType extends string, TPayload> {
	version: typeof CONVERSATION_PROTOCOL_VERSION;
	id: string;
	sequence: number;
	timestamp: string;
	sessionId: string;
	runId: string;
	type: TType;
	payload: TPayload;
}

export interface UIDocument {
	id: string;
	kind: string;
	lifecycle: "ephemeral" | "resumable" | "workspace";
	revision: number;
	content: JsonValue;
	state?: Record<string, JsonValue>;
}

export interface UIAction {
	id: string;
	documentId: string;
	type: string;
	params: Record<string, JsonValue>;
	formState?: Record<string, JsonValue>;
	humanFriendlyMessage?: string;
}

export type ConversationEvent =
	| EventEnvelope<"run.started", { mode: "text" | "voice" | "multimodal" }>
	| EventEnvelope<"text.delta", {
		messageId: string;
		role: ConversationRole;
		delta: string;
	}>
	| EventEnvelope<"audio.delta", {
		streamId: string;
		messageId?: string;
		role: "user" | "assistant";
		encoding: AudioEncoding;
		sampleRate?: number;
		data: string;
	}>
	| EventEnvelope<"transcript.delta", {
		transcriptId: string;
		messageId?: string;
		role: "user" | "assistant";
		delta: string;
		final: boolean;
	}>
	| EventEnvelope<"message.completed", { messageId: string }>
	| EventEnvelope<"tool.requested", {
		callId: string;
		name: string;
		arguments: Record<string, JsonValue>;
	}>
	| EventEnvelope<"tool.started", { callId: string }>
	| EventEnvelope<"tool.progress", { callId: string; update: JsonValue }>
	| EventEnvelope<"tool.completed", { callId: string; result: JsonValue }>
	| EventEnvelope<"tool.failed", { callId: string; error: ProtocolError }>
	| EventEnvelope<"tool.cancelled", { callId: string; reason?: string }>
	| EventEnvelope<"ui.document.upserted", { document: UIDocument }>
	| EventEnvelope<"ui.action", { action: UIAction }>
	| EventEnvelope<"conversation.interrupted", {
		by: "user" | "host" | "provider";
		reason?: string;
		atMessageId?: string;
		atAudioStreamId?: string;
	}>
	| EventEnvelope<"reconnect.started", { attempt: number; reason?: string }>
	| EventEnvelope<"reconnect.succeeded", { attempt: number; resumedFromSequence?: number }>
	| EventEnvelope<"reconnect.failed", { attempt: number; error: ProtocolError; retryable: boolean }>
	| EventEnvelope<"error", { error: ProtocolError; fatal: boolean }>
	| EventEnvelope<"run.completed", { reason: "completed" | "cancelled" | "interrupted" | "error" }>;

export interface ProtocolError {
	code: string;
	message: string;
	provider?: string;
	details?: JsonValue;
}

export type EventOfType<T extends ConversationEvent["type"]> = Extract<ConversationEvent, { type: T }>;

export interface EventMetadata {
	id: string;
	sequence: number;
	timestamp: string;
	sessionId: string;
	runId: string;
}

export function conversationEvent<T extends ConversationEvent["type"]>(
	type: T,
	payload: EventOfType<T>["payload"],
	metadata: EventMetadata,
): EventOfType<T> {
	return {
		version: CONVERSATION_PROTOCOL_VERSION,
		type,
		payload,
		...metadata,
	} as EventOfType<T>;
}

import type {
	ConversationEvent,
	ConversationRole,
	JsonValue,
	ProtocolError,
	UIAction,
	UIDocument,
} from "./events";

export interface ConversationMessageState {
	id: string;
	role: ConversationRole;
	text: string;
	completed: boolean;
}

export interface AudioStreamState {
	id: string;
	messageId?: string;
	role: "user" | "assistant";
	encoding: string;
	sampleRate?: number;
	chunks: string[];
}

export interface TranscriptState {
	id: string;
	messageId?: string;
	role: "user" | "assistant";
	text: string;
	final: boolean;
}

export type ToolCallStatus = "requested" | "running" | "completed" | "failed" | "cancelled";
export interface ToolCallState {
	id: string;
	name: string;
	arguments: Record<string, JsonValue>;
	status: ToolCallStatus;
	updates: JsonValue[];
	result?: JsonValue;
	error?: ProtocolError;
	cancelReason?: string;
}

export interface ConversationState {
	protocolVersion: 1;
	sessionId?: string;
	runId?: string;
	status: "idle" | "active" | "reconnecting" | "completed" | "error";
	mode?: "text" | "voice" | "multimodal";
	lastSequence: number;
	processedEventIds: string[];
	messageOrder: string[];
	messages: Record<string, ConversationMessageState>;
	audioStreams: Record<string, AudioStreamState>;
	transcripts: Record<string, TranscriptState>;
	toolCalls: Record<string, ToolCallState>;
	uiDocuments: Record<string, UIDocument>;
	uiActions: UIAction[];
	interruption?: Extract<ConversationEvent, { type: "conversation.interrupted" }>["payload"];
	reconnectAttempt?: number;
	errors: ProtocolError[];
	completionReason?: Extract<ConversationEvent, { type: "run.completed" }>["payload"]["reason"];
}

export function initialConversationState(): ConversationState {
	return {
		protocolVersion: 1,
		status: "idle",
		lastSequence: -1,
		processedEventIds: [],
		messageOrder: [],
		messages: {},
		audioStreams: {},
		transcripts: {},
		toolCalls: {},
		uiDocuments: {},
		uiActions: [],
		errors: [],
	};
}

function toolCall(state: ConversationState, callId: string): ToolCallState {
	return state.toolCalls[callId] ?? {
		id: callId,
		name: "unknown",
		arguments: {},
		status: "requested",
		updates: [],
	};
}

/**
 * Pure event-log reducer. Duplicate IDs and stale sequence numbers are ignored,
 * making replay and reconnect resume safe. Events are expected to be reduced in
 * ascending sequence order within one run.
 */
export function reduceConversation(state: ConversationState, event: ConversationEvent): ConversationState {
	if (event.version !== state.protocolVersion) return state;
	if (state.processedEventIds.includes(event.id) || event.sequence <= state.lastSequence) return state;

	let next: ConversationState = {
		...state,
		sessionId: event.sessionId,
		runId: event.runId,
		lastSequence: event.sequence,
		processedEventIds: [...state.processedEventIds, event.id],
	};

	switch (event.type) {
		case "run.started":
			return { ...next, status: "active", mode: event.payload.mode, completionReason: undefined };
		case "text.delta": {
			const current = state.messages[event.payload.messageId];
			const isNew = !current;
			const message: ConversationMessageState = current
				? { ...current, text: current.text + event.payload.delta }
				: { id: event.payload.messageId, role: event.payload.role, text: event.payload.delta, completed: false };
			return {
				...next,
				messageOrder: isNew ? [...state.messageOrder, message.id] : state.messageOrder,
				messages: { ...state.messages, [message.id]: message },
			};
		}
		case "message.completed": {
			const current = state.messages[event.payload.messageId];
			if (!current) return next;
			return { ...next, messages: { ...state.messages, [current.id]: { ...current, completed: true } } };
		}
		case "audio.delta": {
			const current = state.audioStreams[event.payload.streamId];
			const stream: AudioStreamState = current
				? { ...current, chunks: [...current.chunks, event.payload.data] }
				: { ...event.payload, id: event.payload.streamId, chunks: [event.payload.data] };
			return { ...next, audioStreams: { ...state.audioStreams, [stream.id]: stream } };
		}
		case "transcript.delta": {
			const current = state.transcripts[event.payload.transcriptId];
			const transcript: TranscriptState = current
				? { ...current, text: current.text + event.payload.delta, final: event.payload.final }
				: {
					id: event.payload.transcriptId,
					messageId: event.payload.messageId,
					role: event.payload.role,
					text: event.payload.delta,
					final: event.payload.final,
				};
			return { ...next, transcripts: { ...state.transcripts, [transcript.id]: transcript } };
		}
		case "tool.requested":
			return {
				...next,
				toolCalls: {
					...state.toolCalls,
					[event.payload.callId]: {
						id: event.payload.callId,
						name: event.payload.name,
						arguments: event.payload.arguments,
						status: "requested",
						updates: [],
					},
				},
			};
		case "tool.started": {
			const call = toolCall(state, event.payload.callId);
			return { ...next, toolCalls: { ...state.toolCalls, [call.id]: { ...call, status: "running" } } };
		}
		case "tool.progress": {
			const call = toolCall(state, event.payload.callId);
			return { ...next, toolCalls: { ...state.toolCalls, [call.id]: { ...call, updates: [...call.updates, event.payload.update] } } };
		}
		case "tool.completed": {
			const call = toolCall(state, event.payload.callId);
			return { ...next, toolCalls: { ...state.toolCalls, [call.id]: { ...call, status: "completed", result: event.payload.result } } };
		}
		case "tool.failed": {
			const call = toolCall(state, event.payload.callId);
			return { ...next, toolCalls: { ...state.toolCalls, [call.id]: { ...call, status: "failed", error: event.payload.error } } };
		}
		case "tool.cancelled": {
			const call = toolCall(state, event.payload.callId);
			return { ...next, toolCalls: { ...state.toolCalls, [call.id]: { ...call, status: "cancelled", cancelReason: event.payload.reason } } };
		}
		case "ui.document.upserted": {
			const previous = state.uiDocuments[event.payload.document.id];
			if (previous && previous.revision >= event.payload.document.revision) return next;
			return { ...next, uiDocuments: { ...state.uiDocuments, [event.payload.document.id]: event.payload.document } };
		}
		case "ui.action":
			return { ...next, uiActions: [...state.uiActions, event.payload.action] };
		case "conversation.interrupted":
			return { ...next, status: "active", interruption: event.payload };
		case "reconnect.started":
			return { ...next, status: "reconnecting", reconnectAttempt: event.payload.attempt };
		case "reconnect.succeeded":
			return { ...next, status: "active", reconnectAttempt: undefined };
		case "reconnect.failed":
			return {
				...next,
				status: event.payload.retryable ? "reconnecting" : "error",
				reconnectAttempt: event.payload.attempt,
				errors: [...state.errors, event.payload.error],
			};
		case "error":
			return { ...next, status: event.payload.fatal ? "error" : state.status, errors: [...state.errors, event.payload.error] };
		case "run.completed":
			return {
				...next,
				status: event.payload.reason === "error" ? "error" : "completed",
				completionReason: event.payload.reason,
			};
	}
}

export function replayConversation(events: readonly ConversationEvent[]): ConversationState {
	return events.reduce(reduceConversation, initialConversationState());
}

import { describe, expect, test } from "bun:test";
import {
	conversationEvent,
	initialConversationState,
	reduceConversation,
	replayConversation,
	type ConversationEvent,
	type EventMetadata,
} from "../../keating/protocol";

const metadata = (sequence: number): EventMetadata => ({
	id: `event-${sequence}`,
	sequence,
	timestamp: `2026-07-18T00:00:${String(sequence).padStart(2, "0")}.000Z`,
	sessionId: "session-1",
	runId: "run-1",
});

describe("conversation protocol", () => {
	test("is JSON round-trip serializable for multimodal and UI payloads", () => {
		const events: ConversationEvent[] = [
			conversationEvent("audio.delta", {
				streamId: "audio-1",
				messageId: "message-1",
				role: "assistant",
				encoding: "pcm16",
				sampleRate: 24_000,
				data: "AQID",
			}, metadata(0)),
			conversationEvent("ui.document.upserted", {
				document: {
					id: "quiz-1",
					kind: "quiz",
					lifecycle: "resumable",
					revision: 1,
					content: { questions: [{ id: "q1", prompt: "Why?" }] },
					state: { answered: false },
				},
			}, metadata(1)),
		];

		expect(JSON.parse(JSON.stringify(events))).toEqual(events);
	});

	test("reduces streaming text, audio, and final transcripts", () => {
		const state = replayConversation([
			conversationEvent("run.started", { mode: "multimodal" }, metadata(0)),
			conversationEvent("text.delta", { messageId: "m1", role: "assistant", delta: "Hel" }, metadata(1)),
			conversationEvent("text.delta", { messageId: "m1", role: "assistant", delta: "lo" }, metadata(2)),
			conversationEvent("audio.delta", { streamId: "a1", messageId: "m1", role: "assistant", encoding: "opus", data: "one" }, metadata(3)),
			conversationEvent("audio.delta", { streamId: "a1", messageId: "m1", role: "assistant", encoding: "opus", data: "two" }, metadata(4)),
			conversationEvent("transcript.delta", { transcriptId: "t1", messageId: "m1", role: "assistant", delta: "Hel", final: false }, metadata(5)),
			conversationEvent("transcript.delta", { transcriptId: "t1", messageId: "m1", role: "assistant", delta: "lo", final: true }, metadata(6)),
			conversationEvent("message.completed", { messageId: "m1" }, metadata(7)),
		]);

		expect(state.status).toBe("active");
		expect(state.messages.m1).toEqual({ id: "m1", role: "assistant", text: "Hello", completed: true });
		expect(state.audioStreams.a1.chunks).toEqual(["one", "two"]);
		expect(state.transcripts.t1).toMatchObject({ text: "Hello", final: true });
	});

	test("tracks parallel tool lifecycles independently", () => {
		const state = replayConversation([
			conversationEvent("tool.requested", { callId: "search", name: "web_search", arguments: { query: "Keating" } }, metadata(0)),
			conversationEvent("tool.requested", { callId: "goal", name: "set_goal", arguments: { topic: "events" } }, metadata(1)),
			conversationEvent("tool.started", { callId: "search" }, metadata(2)),
			conversationEvent("tool.started", { callId: "goal" }, metadata(3)),
			conversationEvent("tool.progress", { callId: "search", update: { results: 2 } }, metadata(4)),
			conversationEvent("tool.completed", { callId: "goal", result: { saved: true } }, metadata(5)),
			conversationEvent("tool.failed", { callId: "search", error: { code: "timeout", message: "Search timed out" } }, metadata(6)),
		]);

		expect(state.toolCalls.goal).toMatchObject({ status: "completed", result: { saved: true } });
		expect(state.toolCalls.search).toMatchObject({ status: "failed", updates: [{ results: 2 }] });
	});

	test("preserves newest UI revision and records host actions", () => {
		const document = { id: "quiz", kind: "quiz", lifecycle: "resumable" as const, revision: 2, content: { title: "Fractions" } };
		const state = replayConversation([
			conversationEvent("ui.document.upserted", { document }, metadata(0)),
			conversationEvent("ui.document.upserted", { document: { ...document, revision: 1, content: { title: "Old" } } }, metadata(1)),
			conversationEvent("ui.action", { action: { id: "answer-1", documentId: "quiz", type: "submit", params: { answer: "1/2" } } }, metadata(2)),
		]);

		expect(state.uiDocuments.quiz).toEqual(document);
		expect(state.uiActions).toHaveLength(1);
	});

	test("models interruption, reconnect, errors, and completion", () => {
		const state = replayConversation([
			conversationEvent("run.started", { mode: "voice" }, metadata(0)),
			conversationEvent("conversation.interrupted", { by: "user", reason: "barge-in", atAudioStreamId: "a1" }, metadata(1)),
			conversationEvent("reconnect.started", { attempt: 1, reason: "network" }, metadata(2)),
			conversationEvent("reconnect.failed", { attempt: 1, retryable: true, error: { code: "offline", message: "Offline" } }, metadata(3)),
			conversationEvent("reconnect.succeeded", { attempt: 2, resumedFromSequence: 3 }, metadata(4)),
			conversationEvent("error", { fatal: false, error: { code: "audio_drop", message: "One chunk dropped" } }, metadata(5)),
			conversationEvent("run.completed", { reason: "completed" }, metadata(6)),
		]);

		expect(state.interruption).toMatchObject({ by: "user", reason: "barge-in" });
		expect(state.errors.map((error) => error.code)).toEqual(["offline", "audio_drop"]);
		expect(state.status).toBe("completed");
		expect(state.completionReason).toBe("completed");
	});

	test("ignores replay duplicates and stale sequence numbers", () => {
		const first = conversationEvent("text.delta", { messageId: "m1", role: "assistant", delta: "once" }, metadata(1));
		const stale = conversationEvent("text.delta", { messageId: "m1", role: "assistant", delta: "stale" }, { ...metadata(0), id: "stale" });
		const once = reduceConversation(initialConversationState(), first);
		const duplicate = reduceConversation(once, first);
		const afterStale = reduceConversation(duplicate, stale);

		expect(afterStale).toBe(duplicate);
		expect(afterStale.messages.m1.text).toBe("once");
	});
});
